77	 */
78	
79	@RestController
80	@CrossOrigin(exposedHeaders = "errors, content-type")
81	@RequestMapping("/api")
82	public class OwnerRestControllerV1 implements OwnersApi {
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    private final OwnerFieldsValidator ownerFieldsValidator;
93	
94	    private final PostcodeValidator postcodeValidator;
95	
96	    private final RegistrationDateValidator registrationDateValidator;
97	
98	    private final HouseholdDuplicateValidator householdDuplicateValidator;
99	
100	    private final IdentityDuplicateValidator identityDuplicateValidator;
101	
102	    private final PossibleDuplicateDetector possibleDuplicateDetector;
103	
104	    private final HouseholdIdGenerator householdIdGenerator;
105	
106	    private final TelephoneNormalizer telephoneNormalizer;
107	
108	    private final EmailNormalizer emailNormalizer;
109	
110	    private final DisposableEmailDomainValidator disposableEmailDomainValidator;
111	
112	    private final AddressResolver addressResolver;
113	
114	    private final MemberIdGenerator memberIdGenerator;
115	
116	    private final NamesakeCounter namesakeCounter;
117	
118	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
119	
120	    private final CityCapacityWarningEvaluator cityCapacityWarningEvaluator;
121	
122	    private final OwnerAuditLogger ownerAuditLogger;
123	
124	    private final OwnerCreationIdempotencyStore idempotencyStore;
125	
126	    private final HttpServletRequest request;
127	
128	    public OwnerRestControllerV1(ClinicService clinicService,
129	                                 OwnerMapper ownerMapper,
130	                                 PetMapper petMapper,
131	                                 VisitMapper visitMapper,
132	                                 OwnerFieldsValidator ownerFieldsValidator,
133	                                 PostcodeValidator postcodeValidator,
134	                                 RegistrationDateValidator registrationDateValidator,
135	                                 HouseholdDuplicateValidator householdDuplicateValidator,
136	                                 IdentityDuplicateValidator identityDuplicateValidator,
137	                                 PossibleDuplicateDetector possibleDuplicateDetector,
138	                                 HouseholdIdGenerator householdIdGenerator,
139	                                 TelephoneNormalizer telephoneNormalizer,
140	                                 EmailNormalizer emailNormalizer,
141	                                 DisposableEmailDomainValidator disposableEmailDomainValidator,
142	                                 AddressResolver addressResolver,
143	                                 MemberIdGenerator memberIdGenerator,
144	                                 NamesakeCounter namesakeCounter,
145	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator,
146	                                 CityCapacityWarningEvaluator cityCapacityWarningEvaluator,
147	                                 OwnerAuditLogger ownerAuditLogger,
148	                                 OwnerCreationIdempotencyStore idempotencyStore,
149	                                 HttpServletRequest request) {
150	        this.clinicService = clinicService;
151	        this.ownerMapper = ownerMapper;
152	        this.petMapper = petMapper;
153	        this.visitMapper = visitMapper;
154	        this.ownerFieldsValidator = ownerFieldsValidator;
155	        this.postcodeValidator = postcodeValidator;
156	        this.registrationDateValidator = registrationDateValidator;
157	        this.householdDuplicateValidator = householdDuplicateValidator;
158	        this.identityDuplicateValidator = identityDuplicateValidator;
159	        this.possibleDuplicateDetector = possibleDuplicateDetector;
160	        this.householdIdGenerator = householdIdGenerator;
161	        this.telephoneNormalizer = telephoneNormalizer;
162	        this.emailNormalizer = emailNormalizer;
163	        this.disposableEmailDomainValidator = disposableEmailDomainValidator;
164	        this.addressResolver = addressResolver;
165	        this.memberIdGenerator = memberIdGenerator;
166	        this.namesakeCounter = namesakeCounter;
167	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
168	        this.cityCapacityWarningEvaluator = cityCapacityWarningEvaluator;
169	        this.ownerAuditLogger = ownerAuditLogger;
170	        this.idempotencyStore = idempotencyStore;
171	        this.request = request;
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
177	        Collection<Owner> owners;
178	        if (lastName != null) {
179	            owners = this.clinicService.findOwnerByLastName(lastName);
180	        } else {
181	            owners = this.clinicService.findAllOwners();
182	        }
183	        if (owners.isEmpty()) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
187	    }
188	
189	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
190	    @Override
191	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
192	        Owner owner = this.clinicService.findOwnerById(ownerId);
193	        if (owner == null) {
194	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	        }
196	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
202	        String idempotencyKey = idempotencyKey();
203	        ResponseEntity<OwnerDto> replay = replayIfDuplicateKey(idempotencyKey);
204	        if (replay != null) {
205	            return replay;
206	        }
207	        addressResolver.resolve(ownerFieldsDto);
208	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
209	        if (!missingFields.isEmpty()) {
210	            throw new MissingOwnerFieldsException(missingFields);
211	        }
212	        HttpHeaders headers = new HttpHeaders();
213	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
214	        Collection<Owner> sameLastName =
215	            activeOwners(this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName()));
216	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
217	        List<Owner> householdMembers = assignHousehold(owner, sameLastName);
218	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
219	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
220	        disposableEmailDomainValidator.validate(owner.getEmail());
221	        postcodeValidator.validate(owner.getPostcode(), owner.getCity());
222	        rejectIfDuplicateIdentity(owner);
223	        applyHouseholdRule(owner, ownerFieldsDto, householdMembers, sameLastName);
224	        registrationDateValidator.validate(owner.getRegistrationDate());
225	        if (owner.getRegistrationDate() == null) {
226	            owner.setRegistrationDate(LocalDate.now());
227	        }
228	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
229	        LocalDate registrationDate = owner.getRegistrationDate();
230	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
231	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
232	            throw new DailyOwnerLimitException(registrationDate);
233	        }
234	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
235	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
236	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
237	            throw new CityOwnerLimitException(owner.getCity());
238	        }
239	        owner.setCapacityWarning(cityCapacityWarningEvaluator.isApproachingCapacity(cityOwnerCount));
240	        owner.setMemberId(assignMemberId(owner));
241	        this.clinicService.saveOwner(owner);
242	        if (idempotencyKey != null) {
243	            idempotencyStore.record(idempotencyKey, owner.getId());
244	        }
245	        ownerAuditLogger.ownerCreated(owner);
246	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
247	        headers.setLocation(UriComponentsBuilder.newInstance()
248	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
249	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
250	    }
251	
252	    /**
253	     * Reads the request's {@code Idempotency-Key} header, treating a blank value as absent.
254	     *
255	     * @return the trimmed key, or {@code null} when the request carries no usable key
256	     */
257	    private String idempotencyKey() {
258	        String key = request.getHeader("Idempotency-Key");
259	        return StringUtils.hasText(key) ? key.trim() : null;
260	    }
261	
262	    /**
263	     * Replays the owner originally created for an already-seen idempotency key, so a repeated
264	     * create returns that owner with 200 instead of storing a duplicate. Returns {@code null}
265	     * when there is no key or the key has not been seen, in which case the create proceeds
266	     * normally.
267	     */
268	    private ResponseEntity<OwnerDto> replayIfDuplicateKey(String idempotencyKey) {
269	        if (idempotencyKey == null) {
270	            return null;
271	        }
272	        return idempotencyStore.find(idempotencyKey)
273	            .map(clinicService::findOwnerById)
274	            .map(ownerMapper::toOwnerDto)
275	            .map(ownerDto -> new ResponseEntity<>(ownerDto, HttpStatus.OK))
276	            .orElse(null);
277	    }
278	
279	    /**
280	     * Assigns the household attributes of an owner about to be created, without touching any
281	     * existing owner. The {@code householdId} is derived deterministically from the owner's last
282	     * name and postcode, so every owner in the same household shares it automatically regardless of
283	     * creation order. The new owner's household size after this create is recorded: the existing
284	     * members that share its household (same last name and postcode) plus the owner itself.
285	     *
286	     * @return the existing members of the owner's household (empty when it starts a new household)
287	     */
288	    private List<Owner> assignHousehold(Owner owner, Collection<Owner> sameLastName) {
289	        owner.setHouseholdId(householdIdGenerator.generate(owner));
290	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
291	        owner.setHouseholdSize(members.size() + 1);
292	        return members;
293	    }
294	
295	    /**
296	     * Computes the member id for an owner about to be created, de-duplicated against the ids already
297	     * assigned to existing owners so that distinct owners always receive distinct ids.
298	     *
299	     * @return the owner's unique member id
300	     */
301	    private String assignMemberId(Owner owner) {
302	        String region = LocalityResolver.localityOf(owner.getPostcode(), owner.getCity());
303	        String baseId = memberIdGenerator.generate(
304	            region, owner.getRegistrationDate(), owner.getTelephone(), owner.getLastName());
305	        List<String> takenIds = clinicService.findOwnersByMemberIdStartingWith(baseId)
306	            .stream()
307	            .map(Owner::getMemberId)
308	            .toList();
309	        return memberIdGenerator.deduplicate(baseId, takenIds);
310	    }
311	
312	    /**
313	     * Applies the household-membership rule once the owner has cleared hard duplicate detection.
314	     * When the owner joins an existing household (same last name and postcode) its membership level
315	     * is capped to at most one above the highest level among the existing members. A member declared
316	     * with {@code sharesHousehold} is, being knowingly registered, not treated as a suspected
317	     * duplicate; an undeclared one still runs the ordinary possible-duplicate detection. When the
318	     * owner starts a new household no cap applies and possible-duplicate detection runs as usual.
319	     */
320	    private void applyHouseholdRule(Owner owner, OwnerFieldsDto ownerFieldsDto,
321	                                    List<Owner> householdMembers, Collection<Owner> sameLastName) {
322	        if (householdMembers.isEmpty()) {
323	            flagPossibleDuplicate(owner, sameLastName);
324	            return;
325	        }
326	        owner.setMembershipLevelCap(MembershipLevelCalculator.householdLevelCeiling(householdMembers));
327	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
328	            owner.setPossibleDuplicate(false);
329	            owner.setPossibleDuplicateOf(null);
330	        } else {
331	            flagPossibleDuplicate(owner, sameLastName);
332	        }
333	    }
334	
335	    /**
336	     * Rejects the owner when its whole derived {@link IdentityKey} already belongs to another
337	     * owner. A full-key match requires an equal telephone, so only owners with the same
338	     * (already normalized) telephone are compared.
339	     *
340	     * @throws DuplicateIdentityException if an existing owner shares the new owner's identity key
341	     */
342	    private void rejectIfDuplicateIdentity(Owner owner) {
343	        Collection<Owner> sameTelephone =
344	            activeOwners(this.clinicService.findOwnersByTelephone(owner.getTelephone()));
345	        if (identityDuplicateValidator.isDuplicate(owner, sameTelephone)) {
346	            throw new DuplicateIdentityException(IdentityKey.of(owner));
347	        }
348	    }
349	
350	    /**
351	     * Filters out soft-deleted owners, so the create endpoint's duplicate and identity checks
352	     * consider only owners that are still active. A soft-deleted owner keeps its row but is
353	     * treated as absent for the purpose of detecting duplicates of a newly created owner.
354	     */
355	    private List<Owner> activeOwners(Collection<Owner> owners) {
356	        return owners.stream().filter(candidate -> !candidate.isDeleted()).toList();
357	    }
358	
359	    /**
360	     * Flags the owner as a soft (possible) duplicate when it is not a hard duplicate yet shares an
361	     * existing owner's last name and postcode with a different telephone. The matching owner's id
362	     * is recorded in {@code possibleDuplicateOf}; when nothing matches the owner is stamped as not
363	     * a possible duplicate. Called after {@link #rejectIfDuplicateIdentity(Owner)}, so any candidate
364	     * seen here is guaranteed not to be a hard duplicate.
365	     */
366	    private void flagPossibleDuplicate(Owner owner, Collection<Owner> sameLastName) {
367	        Owner match = possibleDuplicateDetector.findPossibleDuplicate(owner, sameLastName).orElse(null);
368	        owner.setPossibleDuplicate(match != null);
369	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
370	    }
371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Override
374	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
375	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
376	        if (currentOwner == null) {
377	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
378	        }
379	        currentOwner.setAddress(ownerFieldsDto.getAddress());
380	        currentOwner.setCity(ownerFieldsDto.getCity());
381	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
382	        currentOwner.setLastName(ownerFieldsDto.getLastName());
383	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
384	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
385	        this.clinicService.saveOwner(currentOwner);
386	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
387	    }
388	
389	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
390	    @Transactional
391	    @Override
392	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
393	        Owner owner = this.clinicService.findOwnerById(ownerId);
394	        if (owner == null) {
395	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
396	        }
397	        owner.setDeleted(true);
398	        this.clinicService.saveOwner(owner);
399	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
400	    }
401	
402	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
403	    @Override
404	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
405	        Owner owner = this.clinicService.findOwnerById(ownerId);
406	        if (owner == null) {
407	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	        }
409	        HttpHeaders headers = new HttpHeaders();
410	        Pet pet = petMapper.toPet(petFieldsDto);
411	        owner.setId(ownerId);
412	        pet.setOwner(owner);
413	        pet.getType().setName(null);
414	        this.clinicService.savePet(pet);
415	        PetDto petDto = petMapper.toPetDto(pet);
416	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
417	            .buildAndExpand(pet.getId()).toUri());
418	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
419	    }
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Override
423	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
424	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
425	        if (currentOwner != null) {
426	            Pet currentPet = this.clinicService.findPetById(petId);
427	            if (currentPet != null) {
428	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
429	                currentPet.setName(petFieldsDto.getName());
430	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
431	                this.clinicService.savePet(currentPet);
432	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
433	            }
434	        }
435	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Override
440	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
441	        HttpHeaders headers = new HttpHeaders();
442	        Visit visit = visitMapper.toVisit(visitFieldsDto);
443	        Pet pet = new Pet();
444	        pet.setId(petId);
445	        visit.setPet(pet);
446	        this.clinicService.saveVisit(visit);
447	        VisitDto visitDto = visitMapper.toVisitDto(visit);
448	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
449	            .buildAndExpand(visit.getId()).toUri());
450	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
451	    }
452	
453	
