16	package org.springframework.samples.petclinic.rest;
17	
18	import java.util.concurrent.atomic.AtomicLong;
19	
20	import org.slf4j.Logger;
21	import org.slf4j.LoggerFactory;
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.stereotype.Component;
24	
25	import tools.jackson.databind.ObjectMapper;
26	
27	/**
28	 * Emits the immutable {@link OwnerCreatedEvent} to the dedicated {@code AUDIT} logger as JSON,
29	 * assigning each created owner the next value of a monotonically increasing sequence.
30	 */
31	@Component
32	public class OwnerCreatedEventEmitter {
33	
34	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
35	
36	    private final AtomicLong sequence = new AtomicLong();
37	
38	    private final ObjectMapper objectMapper;
39	
40	    public OwnerCreatedEventEmitter(ObjectMapper objectMapper) {
41	        this.objectMapper = objectMapper;
42	    }
43	
44	    /**
45	     * Emit the structured {@code OWNER_CREATED} event for a freshly persisted owner, stamping it
46	     * with the next sequence number.
47	     *
