package org.springframework.samples.petclinic.rest;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.stereotype.Component;

/**
 * Enqueues the welcome notification for a freshly created owner by emitting a line to the
 * dedicated {@code NOTIFY} logger, keeping notification concerns out of the request-handling
 * controller.
 */
@Component
public class WelcomeNotifier {

    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");

    /**
     * Enqueue a welcome notification for a successfully created owner, carrying its id and
     * member id.
     *
     * @param owner the persisted owner
     */
    public void welcome(Owner owner) {
        NOTIFY.info("Welcome owner: id={} memberId={}", owner.getId(), owner.getMemberId());
    }
}

